styles:
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&display=swap');

    * {
      margin: 0;
      padding: 0;
      box-sizing: border-box;
    }

    .dgs-llm-page {
      font-family: 'DM Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
      background: #000000;
      color: #ffffff;
      line-height: 1.6;
    }

    :root {
      --brand-magenta: #E91E8C;
      --brand-purple: #B91E8C;
      --brand-orange: #FF6B35;
      --gradient-brand: linear-gradient(135deg, var(--brand-magenta) 0%, var(--brand-purple) 50%, var(--brand-orange) 100%);
    }

    .dgs-container {
      max-width: 1200px;
      margin: 0 auto;
      padding: 0 20px;
    }

    @keyframes gradientPulse {
      0%, 100% { background-position: 0% 50%; filter: brightness(1); }
      50% { background-position: 100% 50%; filter: brightness(1.3); }
    }

    @keyframes pulse {
      0%, 100% { transform: scale(1); opacity: 1; box-shadow: 0 0 0 0 rgba(233, 30, 140, 0.7); }
      50% { transform: scale(1.3); opacity: 0.8; box-shadow: 0 0 0 10px rgba(233, 30, 140, 0); }
    }

    @keyframes float {
      0%, 100% { transform: translate(0, 0) scale(1) rotate(0deg); }
      33% { transform: translate(40px, -40px) scale(1.15) rotate(5deg); }
      66% { transform: translate(-30px, 30px) scale(0.9) rotate(-5deg); }
    }

    @keyframes fadeInUp {
      from { opacity: 0; transform: translateY(40px); }
      to { opacity: 1; transform: translateY(0); }
    }

    .dgs-gradient-text {
      background: linear-gradient(270deg, var(--brand-magenta), var(--brand-purple), var(--brand-orange), var(--brand-magenta));
      background-size: 400% 400%;
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
      display: inline-block;
      animation: gradientPulse 4s ease infinite;
    }

    /* ─── HERO ─────────────────────────────────────── */
    .dgs-llm-hero {
      position: relative;
      min-height: 100vh;
      display: flex;
      align-items: center;
      justify-content: center;
      overflow: hidden;
      padding: 120px 20px 100px;
    }

    .dgs-hero-container {
      max-width: 1100px;
      margin: 0 auto;
      text-align: center;
      position: relative;
      z-index: 2;
    }

    .dgs-elite-badge {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      background: rgba(255, 255, 255, 0.05);
      backdrop-filter: blur(20px);
      -webkit-backdrop-filter: blur(20px);
      border: 1px solid rgba(255, 255, 255, 0.15);
      box-shadow: 0 8px 32px 0 rgba(233, 30, 140, 0.15);
      border-radius: 50px;
      padding: 12px 28px;
      font-size: 15px;
      font-weight: 500;
      margin-bottom: 40px;
      animation: fadeInUp 0.6s ease-out;
      letter-spacing: 0.5px;
    }

    .dgs-pulse-dot {
      width: 10px;
      height: 10px;
      background: var(--gradient-brand);
      border-radius: 50%;
      animation: pulse 2s ease-in-out infinite;
    }

    .dgs-hero-title {
      font-size: clamp(42px, 7vw, 68px);
      font-weight: 700;
      line-height: 1.2;
      margin-bottom: 28px;
      animation: fadeInUp 0.8s ease-out 0.2s backwards;
    }

    .dgs-hero-description {
      font-size: clamp(18px, 2.5vw, 22px);
      color: rgba(255, 255, 255, 0.8);
      max-width: 900px;
      margin: 0 auto 56px;
      line-height: 1.8;
      animation: fadeInUp 1s ease-out 0.4s backwards;
    }

    .dgs-trust-badges {
      display: flex;
      flex-wrap: wrap;
      justify-content: center;
      gap: 20px;
      margin-bottom: 56px;
      animation: fadeInUp 1.1s ease-out 0.5s backwards;
    }

    .dgs-trust-item {
      display: flex;
      align-items: center;
      gap: 10px;
      font-size: 15px;
      color: rgba(255, 255, 255, 0.85);
      padding: 8px 20px;
      background: rgba(255, 255, 255, 0.03);
      backdrop-filter: blur(10px);
      border: 1px solid rgba(255, 255, 255, 0.1);
      border-radius: 30px;
    }

    .dgs-trust-item::before {
      content: '';
      width: 5px;
      height: 5px;
      background: var(--gradient-brand);
      border-radius: 50%;
    }

    .dgs-hero-cta {
      display: flex;
      flex-wrap: wrap;
      justify-content: center;
      gap: 18px;
      animation: fadeInUp 1.2s ease-out 0.6s backwards;
    }

    .dgs-btn-primary,
    .dgs-btn-secondary,
    .dgs-btn-whatsapp {
      display: inline-flex;
      align-items: center;
      gap: 14px;
      padding: 18px 36px;
      border-radius: 10px;
      font-weight: 600;
      font-size: 17px;
      text-decoration: none;
      transition: all 0.3s ease;
      border: 1px solid transparent;
      position: relative;
      overflow: hidden;
    }

    .dgs-btn-primary {
      background: linear-gradient(270deg, var(--brand-magenta), var(--brand-purple), var(--brand-orange), var(--brand-magenta));
      background-size: 400% 400%;
      color: #ffffff;
      animation: gradientPulse 4s ease infinite;
      box-shadow: 0 8px 32px rgba(233, 30, 140, 0.3);
    }

    .dgs-btn-primary:hover {
      transform: translateY(-3px);
      box-shadow: 0 12px 40px rgba(233, 30, 140, 0.4);
    }

    .dgs-btn-secondary {
      background: rgba(255, 255, 255, 0.05);
      backdrop-filter: blur(20px);
      -webkit-backdrop-filter: blur(20px);
      color: #ffffff;
      border-color: rgba(255, 255, 255, 0.2);
    }

    .dgs-btn-secondary:hover {
      background: rgba(255, 255, 255, 0.1);
      border-color: var(--brand-magenta);
      box-shadow: 0 8px 32px rgba(233, 30, 140, 0.2);
    }

    .dgs-btn-whatsapp {
      background: rgba(255, 255, 255, 0.05);
      backdrop-filter: blur(20px);
      -webkit-backdrop-filter: blur(20px);
      color: #ffffff;
      border-color: rgba(255, 255, 255, 0.2);
    }

    .dgs-btn-whatsapp:hover {
      background: rgba(37, 211, 102, 0.15);
      border-color: #25D366;
      box-shadow: 0 8px 32px rgba(37, 211, 102, 0.2);
    }

    .dgs-hero-bg-element {
      position: absolute;
      border-radius: 50%;
      filter: blur(140px);
      opacity: 0.15;
    }

    .dgs-hero-bg-1 {
      width: 600px; height: 600px;
      background: radial-gradient(circle, var(--brand-magenta) 0%, transparent 70%);
      top: -150px; left: -150px;
      animation: float 25s ease-in-out infinite, gradientPulse 8s ease infinite;
    }

    .dgs-hero-bg-2 {
      width: 500px; height: 500px;
      background: radial-gradient(circle, var(--brand-purple) 0%, transparent 70%);
      top: 40%; right: -150px;
      animation: float 30s ease-in-out infinite 5s, gradientPulse 10s ease infinite;
    }

    .dgs-hero-bg-3 {
      width: 700px; height: 700px;
      background: radial-gradient(circle, var(--brand-orange) 0%, transparent 70%);
      bottom: -250px; left: 35%;
      animation: float 35s ease-in-out infinite 10s, gradientPulse 12s ease infinite;
    }

    /* ─── CLIENTS ──────────────────────────────────── */
    .dgs-clients {
      padding: 80px 20px;
      background: rgba(255, 255, 255, 0.01);
      backdrop-filter: blur(10px);
      border-top: 1px solid rgba(255, 255, 255, 0.05);
      border-bottom: 1px solid rgba(255, 255, 255, 0.05);
    }

    .dgs-clients-title {
      text-align: center;
      font-size: 14px;
      text-transform: uppercase;
      letter-spacing: 2.5px;
      color: rgba(255, 255, 255, 0.45);
      margin-bottom: 50px;
      font-weight: 500;
    }

    .dgs-clients-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
      gap: 50px;
      align-items: center;
      max-width: 1100px;
      margin: 0 auto;
    }

    .dgs-client-logo {
      display: flex;
      align-items: center;
      justify-content: center;
      opacity: 0.7;
      transition: opacity 0.3s ease, transform 0.3s ease;
    }

    .dgs-client-logo:hover { opacity: 1; transform: scale(1.05); }

    .dgs-client-logo img { max-width: 130px; height: auto; }

    /* ─── CONTENT SECTIONS ─────────────────────────── */
    .dgs-content-section { padding: 120px 20px; }
    .dgs-content-section.alt-bg { background: rgba(255, 255, 255, 0.01); }

    .dgs-content-wrapper {
      max-width: 1000px;
      margin: 0 auto;
    }

    .dgs-content-wrapper h2 {
      font-size: clamp(32px, 5vw, 48px);
      font-weight: 700;
      margin-bottom: 24px;
      line-height: 1.2;
    }

    .dgs-content-wrapper h3 {
      font-size: clamp(26px, 4vw, 36px);
      font-weight: 700;
      margin-bottom: 20px;
      margin-top: 48px;
      line-height: 1.3;
    }

    .dgs-content-wrapper p {
      font-size: 18px;
      color: rgba(255, 255, 255, 0.8);
      line-height: 1.8;
      margin-bottom: 20px;
    }

    .dgs-content-wrapper ul {
      list-style: none;
      padding: 0;
      margin: 24px 0;
    }

    .dgs-content-wrapper ul li {
      padding: 10px 0;
      padding-left: 28px;
      position: relative;
      color: rgba(255, 255, 255, 0.8);
      font-size: 17px;
      line-height: 1.7;
    }

    .dgs-content-wrapper ul li:before {
      content: "";
      position: absolute;
      left: 0; top: 16px;
      width: 14px; height: 2px;
      background: var(--gradient-brand);
    }

    .dgs-content-wrapper strong { color: #ffffff; font-weight: 600; }
    .dgs-content-wrapper em { color: rgba(255,255,255,0.9); font-style: italic; }

    /* ─── NUMBERED STEPS ───────────────────────────── */
    .dgs-numbered-steps {
      list-style: none;
      padding: 0;
      margin: 28px 0;
      counter-reset: steps;
    }

    .dgs-numbered-steps li {
      counter-increment: steps;
      font-size: 17px;
      color: rgba(255, 255, 255, 0.8);
      line-height: 1.75;
      padding: 18px 20px 18px 64px;
      position: relative;
      background: rgba(255, 255, 255, 0.03);
      backdrop-filter: blur(20px);
      border: 1px solid rgba(255, 255, 255, 0.08);
      border-radius: 10px;
      margin-bottom: 12px;
      transition: all 0.3s ease;
    }

    .dgs-numbered-steps li:hover {
      border-color: rgba(233, 30, 140, 0.3);
      background: rgba(255, 255, 255, 0.05);
    }

    .dgs-numbered-steps li::before {
      content: counter(steps);
      position: absolute;
      left: 20px;
      top: 50%;
      transform: translateY(-50%);
      font-size: 13px;
      font-weight: 700;
      color: var(--brand-magenta);
      width: 28px; height: 28px;
      border: 1px solid rgba(233, 30, 140, 0.4);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      line-height: 28px;
      text-align: center;
    }

    /* ─── SECTION HEADER ───────────────────────────── */
    .dgs-section-header {
      text-align: center;
      max-width: 900px;
      margin: 0 auto 70px;
    }

    .dgs-section-tag {
      display: inline-block;
      padding: 8px 20px;
      background: rgba(255, 255, 255, 0.05);
      backdrop-filter: blur(20px);
      border: 1px solid rgba(255, 255, 255, 0.15);
      border-radius: 50px;
      font-size: 13px;
      text-transform: uppercase;
      letter-spacing: 2px;
      margin-bottom: 20px;
      color: rgba(255, 255, 255, 0.7);
      font-weight: 500;
    }

    .dgs-section-title {
      font-size: clamp(38px, 6vw, 54px);
      font-weight: 700;
      margin-bottom: 20px;
      line-height: 1.2;
    }

    .dgs-section-subtitle {
      font-size: 19px;
      color: rgba(255, 255, 255, 0.7);
      line-height: 1.8;
    }

    /* ─── APPROACH / PILLARS ───────────────────────── */
    .dgs-pillars-section { padding: 120px 20px; }

    .dgs-pillars-grid {
      display: grid;
      gap: 28px;
      max-width: 1100px;
      margin: 0 auto;
    }

    .dgs-pillar-card {
      background: rgba(255, 255, 255, 0.03);
      backdrop-filter: blur(20px);
      -webkit-backdrop-filter: blur(20px);
      border: 1px solid rgba(255, 255, 255, 0.1);
      border-left: 3px solid transparent;
      border-image: var(--gradient-brand) 1;
      border-radius: 12px;
      padding: 42px;
      transition: all 0.4s ease;
      position: relative;
      overflow: hidden;
    }

    .dgs-pillar-card::before {
      content: '';
      position: absolute;
      top: 0; left: 0;
      width: 100%; height: 100%;
      background: linear-gradient(135deg, rgba(233,30,140,0.05) 0%, rgba(255,107,53,0.05) 100%);
      opacity: 0;
      transition: opacity 0.4s ease;
      pointer-events: none;
    }

    .dgs-pillar-card:hover {
      background: rgba(255, 255, 255, 0.05);
      transform: translateX(10px);
      box-shadow: 0 10px 40px rgba(233, 30, 140, 0.1);
    }

    .dgs-pillar-card:hover::before { opacity: 1; }

    .dgs-pillar-number {
      font-size: 15px;
      font-weight: 600;
      background: var(--gradient-brand);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
      margin-bottom: 16px;
      letter-spacing: 1.5px;
    }

    .dgs-pillar-title {
      font-size: 26px;
      font-weight: 700;
      margin-bottom: 16px;
    }

    .dgs-pillar-description {
      color: rgba(255, 255, 255, 0.75);
      line-height: 1.8;
      margin-bottom: 24px;
      font-size: 17px;
    }

    .dgs-pillar-list {
      list-style: none;
      padding: 0;
    }

    .dgs-pillar-list li {
      padding: 10px 0;
      padding-left: 28px;
      position: relative;
      color: rgba(255, 255, 255, 0.75);
      font-size: 16px;
    }

    .dgs-pillar-list li:before {
      content: "";
      position: absolute;
      left: 0; top: 16px;
      width: 14px; height: 2px;
      background: var(--gradient-brand);
    }

    /* ─── IMPACT CARDS ─────────────────────────────── */
    .dgs-impact-grid {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      gap: 28px;
      margin: 40px 0;
      align-items: stretch;
    }

    .dgs-impact-card {
      background: rgba(255, 255, 255, 0.03);
      backdrop-filter: blur(20px);
      -webkit-backdrop-filter: blur(20px);
      border: 1px solid rgba(255, 255, 255, 0.1);
      border-radius: 14px;
      padding: 36px 28px;
      transition: all 0.4s ease;
      position: relative;
      overflow: hidden;
      height: 100%;
      display: flex;
      flex-direction: column;
    }

    .dgs-impact-card::before {
      content: '';
      position: absolute;
      top: 0; left: 0; right: 0;
      height: 3px;
      background: var(--gradient-brand);
      opacity: 0;
      transition: opacity 0.4s ease;
    }

    .dgs-impact-card:hover {
      transform: translateY(-6px);
      border-color: rgba(233, 30, 140, 0.35);
      box-shadow: 0 15px 50px rgba(233, 30, 140, 0.12);
    }

    .dgs-impact-card:hover::before { opacity: 1; }

    .dgs-impact-title {
      font-size: 18px;
      font-weight: 700;
      margin-bottom: 12px;
      color: #ffffff;
    }

    .dgs-impact-desc {
      font-size: 15px;
      color: rgba(255, 255, 255, 0.65);
      line-height: 1.75;
    }

    /* ─── CTA SECTION ──────────────────────────────── */
    .dgs-cta-section {
      padding: 120px 20px;
      background: linear-gradient(135deg, rgba(233,30,140,0.05) 0%, rgba(185,30,140,0.05) 50%, rgba(255,107,53,0.05) 100%);
      text-align: center;
      position: relative;
      overflow: hidden;
    }

    .dgs-cta-content {
      max-width: 800px;
      margin: 0 auto;
      position: relative;
      z-index: 2;
      padding: 60px 40px;
      background: rgba(255, 255, 255, 0.03);
      backdrop-filter: blur(30px);
      -webkit-backdrop-filter: blur(30px);
      border: 1px solid rgba(255, 255, 255, 0.15);
      border-radius: 24px;
      box-shadow: 0 8px 32px rgba(233, 30, 140, 0.15);
    }

    .dgs-cta-title {
      font-size: clamp(38px, 6vw, 54px);
      font-weight: 700;
      margin-bottom: 24px;
    }

    .dgs-cta-description {
      font-size: 19px;
      color: rgba(255, 255, 255, 0.8);
      margin-bottom: 48px;
      line-height: 1.8;
    }

    .dgs-cta-buttons {
      display: flex;
      flex-wrap: wrap;
      gap: 18px;
      justify-content: center;
    }

    /* ─── FAQ ──────────────────────────────────────── */
    .dgs-faq-section { padding: 120px 20px; }

    .dgs-faq-container {
      max-width: 950px;
      margin: 0 auto;
    }

    .dgs-faq-item {
      background: rgba(255, 255, 255, 0.03);
      backdrop-filter: blur(20px);
      -webkit-backdrop-filter: blur(20px);
      border: 1px solid rgba(255, 255, 255, 0.1);
      border-radius: 12px;
      margin-bottom: 20px;
      overflow: hidden;
      transition: all 0.3s ease;
    }

    .dgs-faq-item:hover {
      border-color: rgba(233, 30, 140, 0.3);
      box-shadow: 0 8px 32px rgba(233, 30, 140, 0.1);
    }

    .dgs-faq-question {
      padding: 28px;
      font-size: 19px;
      font-weight: 600;
      cursor: pointer;
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 24px;
    }

    .dgs-faq-answer {
      padding: 0 28px 28px;
      color: rgba(255, 255, 255, 0.75);
      line-height: 1.8;
      font-size: 17px;
      display: none;
    }

    .dgs-faq-item.active .dgs-faq-answer { display: block; }

    .dgs-faq-toggle {
      font-size: 24px;
      transition: transform 0.3s ease;
      background: var(--gradient-brand);
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
      flex-shrink: 0;
    }

    .dgs-faq-item.active .dgs-faq-toggle { transform: rotate(45deg); }

    /* ─── FINAL CTA ────────────────────────────────── */
    .dgs-final-cta {
      padding: 120px 20px;
      background: rgba(255, 255, 255, 0.01);
    }

    .dgs-final-cta-container {
      max-width: 800px;
      margin: 0 auto;
      text-align: center;
    }

    .dgs-final-cta-container h2 {
      font-size: clamp(38px, 6vw, 54px);
      font-weight: 700;
      margin-bottom: 20px;
    }

    .dgs-final-cta-container > p {
      font-size: 19px;
      color: rgba(255, 255, 255, 0.75);
      margin-bottom: 50px;
      line-height: 1.8;
    }

    .dgs-form-shortcode {
      background: rgba(255, 255, 255, 0.03);
      backdrop-filter: blur(30px);
      -webkit-backdrop-filter: blur(30px);
      border: 1px solid rgba(255, 255, 255, 0.15);
      border-radius: 16px;
      padding: 50px;
      margin-bottom: 40px;
      box-shadow: 0 8px 32px rgba(233, 30, 140, 0.1);
    }
.dgs-contact-info {
      display: flex;
      justify-content: center;
      gap: 28px;
      flex-wrap: wrap;
    }

    .dgs-contact-item {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      padding: 16px 28px;
      background: rgba(255, 255, 255, 0.05);
      backdrop-filter: blur(20px);
      -webkit-backdrop-filter: blur(20px);
      border: 1px solid rgba(255, 255, 255, 0.15);
      border-radius: 10px;
      color: rgba(255, 255, 255, 0.85);
      text-decoration: none;
      font-size: 16px;
      transition: all 0.3s ease;
    }

    .dgs-contact-item:hover {
      border-color: var(--brand-magenta);
      background: rgba(255, 255, 255, 0.08);
      box-shadow: 0 8px 32px rgba(233, 30, 140, 0.2);
      transform: translateY(-2px);
    }

    .dgs-contact-item svg { width: 20px; height: 20px; }

    /* ─── RESPONSIVE ───────────────────────────────── */
    @media (max-width: 768px) {
      .dgs-hero-cta { flex-direction: column; align-items: stretch; }
      .dgs-btn-primary, .dgs-btn-secondary, .dgs-btn-whatsapp { justify-content: center; }
      .dgs-clients-grid { grid-template-columns: repeat(2, 1fr); gap: 30px; }
      .dgs-content-section, .dgs-pillars-section { padding: 80px 20px; }
      .dgs-impact-grid { grid-template-columns: 1fr; }
      .dgs-cta-content { padding: 40px 28px; }
      .dgs-form-shortcode { padding: 32px 24px; }
      .dgs-pillar-card { padding: 32px; }
    }

    .dgs-inline-link{
      color:#ffffff;
      text-decoration:none;
      border-bottom:1px solid rgba(255,255,255,0.25);
      transition:all 0.25s ease;
    }
    .dgs-inline-link:hover{
      color:#ffffff;
      border-bottom-color: var(--brand-magenta);
      box-shadow: inset 0 -1px 0 rgba(233,30,140,0.35);
    }
    .dgs-updated-line{
      margin-top:24px;
      font-size:14px;
      color:rgba(255,255,255,0.58);
      letter-spacing:.02em;
      animation: fadeInUp 1.25s ease-out 0.7s backwards;
    }
    .dgs-updated-line strong{color:#fff;font-weight:600;}


.llm-upgrade, .llm-upgrade * { box-sizing:border-box; font-family:Inter, Arial, sans-serif; }
.llm-upgrade{
  --bg:#07060D; --bg2:#0D0B18; --bg3:#141122;
  --silver:#F0EDF8; --body:#C8C5D8; --muted:#8A87A0; --dim:#5C596E;
  --line:rgba(255,255,255,.08); --ln2:rgba(255,255,255,.15);
  --green:#22C55E;
  color:var(--body);
}
.llm-upgrade img{display:block;max-width:100%;}
